import{_ as o,o as r,c as t,a3 as s}from"./chunks/framework.BzWmN0d8.js";const p=JSON.parse('{"title":"Troubleshooting & FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1788425513000}'),n={name:"guide/troubleshooting.md"};function a(d,e,c,i,l,u){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting-faq" tabindex="-1">Troubleshooting &amp; FAQ <a class="header-anchor" href="#troubleshooting-faq" aria-label="Permalink to &quot;Troubleshooting &amp; FAQ&quot;">​</a></h1><p>A self-check list for the most common &quot;why am I not seeing logs?&quot; situations.</p><h2 id="_1-console-output-causes-infinite-recursion-stack-overflow" tabindex="-1">1. Console output causes infinite recursion / stack overflow <a class="header-anchor" href="#_1-console-output-causes-infinite-recursion-stack-overflow" aria-label="Permalink to &quot;1. Console output causes infinite recursion / stack overflow&quot;">​</a></h2><p><strong>Symptom:</strong> the app hangs or throws <code>Maximum call stack size exceeded</code> as soon as you log.</p><p><strong>Cause:</strong> a transport (or a formatter/plugin) calls <code>console.log</code>/<code>console.error</code> while <em>you</em> have redirected the console into <code>lograil</code> via <code>redirectConsole()</code>. Note: <code>lograil</code> does <strong>not</strong> redirect <code>console.*</code> by default — this only happens when you explicitly call <code>logger.redirectConsole()</code>. The redirected <code>console.*</code> calls back into the logger → loop.</p><p><strong>Check</strong></p><ul><li>Did you call <code>redirectConsole()</code>? If so, remember it captures <code>console.*</code> and re-emits them through the logger. Your own transports/plugins must <strong>not</strong> call <code>console.*</code> for the same levels. If you did <strong>not</strong> call it, skip this section — your recursion is coming from elsewhere (e.g. a transport calling <code>console</code>).</li><li>Inside <code>onError</code> or a custom transport, use the <strong>raw</strong> console (<code>console.error</code>) — <code>lograil</code> deliberately keeps a pre-redirect reference for exactly this, but if you captured <code>console</code> yourself, use <code>process.stderr</code> or a dedicated stderr sink instead.</li></ul><p><strong>Fix:</strong> in error handlers and custom sinks, write to <code>process.stderr</code>/a file, or use a transport that doesn&#39;t round-trip through the redirected console.</p><h2 id="_2-browser-bundler-error-can-t-resolve-node-fs-node-path-node-os" tabindex="-1">2. Browser bundler error: can&#39;t resolve <code>node:fs</code> / <code>node:path</code> / <code>node:os</code> <a class="header-anchor" href="#_2-browser-bundler-error-can-t-resolve-node-fs-node-path-node-os" aria-label="Permalink to &quot;2. Browser bundler error: can&#39;t resolve `node:fs` / `node:path` / `node:os`&quot;">​</a></h2><p><strong>Symptom:</strong> webpack / Vite / Rollup reports <code>Module not found: Can&#39;t resolve &#39;node:fs&#39;</code> or <code>Failed to resolve import &quot;node:fs/promises&quot;</code> when bundling a page that imports <code>lograil</code>.</p><p><strong>Cause:</strong> an outdated <code>lograil</code> version. Modern releases never resolve Node built-ins directly — they go through an internal <code>shims</code> layer that the <code>browser</code> field swaps for a browser stub at build time, so the import resolves cleanly (verified by bundler integration tests).</p><p><strong>Fix:</strong> upgrade <code>lograil</code> to the latest version. If you&#39;re already on a recent release and still see the error, check that your bundler doesn&#39;t force-resolve <code>browser</code> mappings off, or that you aren&#39;t importing <code>lograil</code> from an unbundled <code>node_modules</code> path outside your build (e.g. a CDN that bypasses the <code>browser</code> field).</p><h2 id="_3-renderer-process-produces-no-logs" tabindex="-1">3. Renderer process produces no logs <a class="header-anchor" href="#_3-renderer-process-produces-no-logs" aria-label="Permalink to &quot;3. Renderer process produces no logs&quot;">​</a></h2><p><strong>Symptom:</strong> logging works in the main process but the renderer is silent (or renderer logs never reach the main-process <code>renderer.log</code> file).</p><p><strong>Background:</strong> with the default Electron runtime this is <strong>automatic</strong> — the renderer logger forwards to the main process over IPC, and the main logger writes a separate <code>renderer.{date}.log</code>. You normally do nothing. If it isn&#39;t working, one of these is true: you opted out of the automatic wiring, you built the logger with a non-Electron runtime, or the renderer can&#39;t reach the <code>electron</code> module and silently fell back to the Web runtime.</p><p><strong>Check</strong></p><ul><li>Are you using the default <code>logger</code> / <code>createLogger()</code> (no explicit <code>runtime</code>)? If so, forwarding + receiving are wired for you — no <code>ElectronIpcTransport</code> or <code>registerIpcReceiver</code> call is needed.</li><li>If you <strong>opted out</strong> (<code>createElectronRendererRuntime({ forwardToMain: false })</code> or <code>createElectronMainRuntime({ receiveFromRenderer: false })</code>) or use a custom runtime: did you manually add <code>ElectronIpcTransport</code> in the <strong>renderer</strong> and call <code>registerIpcReceiver((entry) =&gt; logger.ingestEntry(entry))</code> in the <strong>main</strong>?</li><li>Is the channel correct? Both sides default to <code>lograil:log</code> (<code>LOGRAIL_CHANNEL</code>); if you override it, override on <strong>both</strong> sides.</li><li>Packaged app with <code>contextIsolation: true</code> + <code>nodeIntegration: false</code>? The renderer can&#39;t <code>require(&#39;electron&#39;)</code>, so lograil can&#39;t detect Electron and falls back to the Web runtime (console only). Use a preload bridge and pass it via <code>createElectronRendererRuntime({ ipcRenderer })</code> (see the <a href="./runtime-electron">Electron guide</a>).</li><li>Rule out a level filter: <code>logger.setLevel(&#39;trace&#39;)</code> temporarily.</li></ul><p>See the <a href="./runtime-electron">Electron guide</a>.</p><h2 id="_4-otlp-endpoint-doesn-t-receive-anything" tabindex="-1">4. OTLP endpoint doesn&#39;t receive anything <a class="header-anchor" href="#_4-otlp-endpoint-doesn-t-receive-anything" aria-label="Permalink to &quot;4. OTLP endpoint doesn&#39;t receive anything&quot;">​</a></h2><p><strong>Symptom:</strong> <code>OtlpTransport</code> is added but the collector shows no logs.</p><p><strong>Check</strong></p><ul><li>Is the endpoint reachable from the process that owns the transport? (In an Electron renderer the network egress may be restricted; prefer sending from the main process, or forward renderer logs via <code>ElectronIpcTransport</code>.)</li><li><code>OtlpTransport</code> <strong>batches</strong> (<code>batchSize</code>, default 100) and flushes asynchronously. For a quick test, call <code>await logger.flush()</code> at the end of your run, or lower <code>batchSize</code>.</li><li><code>fetch</code> failures are reported through <code>onError</code> (default: <code>console.error</code>). Add an explicit <code>onError</code> to see HTTP/connection errors.</li><li>Confirm the collector URL: OTLP/HTTP JSON expects <code>…/v1/logs</code>. A 404/401 usually means the path or auth header is wrong.</li><li>Firewall / proxy: the request is a normal <code>fetch</code>; ensure egress is allowed.</li></ul><h2 id="_5-log-files-aren-t-rotating" tabindex="-1">5. Log files aren&#39;t rotating <a class="header-anchor" href="#_5-log-files-aren-t-rotating" aria-label="Permalink to &quot;5. Log files aren&#39;t rotating&quot;">​</a></h2><p><strong>Symptom:</strong> a single file keeps growing, or no dated files appear.</p><p><strong>Check</strong></p><ul><li><code>FileTransport</code> only works where the Node <code>fs</code> API exists — the <strong>main</strong> process / Node runtime, not a browser or renderer Web Worker.</li><li><code>rotate-time</code> mode (default) writes <code>&lt;appName&gt;.{YYYY-MM-DD}.0.log</code>. Check the date stamp format and that the directory is writable. The directory is created automatically (<code>mkdir -p</code>).</li><li>Rotation triggers when a write would exceed <code>maxSize</code> (<code>rotate-size</code> / <code>single-truncate</code>), or cross the <code>hour</code>/<code>day</code> boundary (<code>rotate-time</code>), or when your <code>shouldRotate</code> predicate returns <code>true</code> (<code>rotate-custom</code>). A tiny <code>maxSize</code> / high volume makes rotation happen fast; verify <code>maxFiles</code> allows more than one generation.</li><li>The file handle opens on the <strong>first actual</strong> write. If nothing is logged, no file is created — that&#39;s expected.</li></ul><h2 id="_6-logs-appear-out-of-order-duplicated-across-transports" tabindex="-1">6. Logs appear out of order / duplicated across transports <a class="header-anchor" href="#_6-logs-appear-out-of-order-duplicated-across-transports" aria-label="Permalink to &quot;6. Logs appear out of order / duplicated across transports&quot;">​</a></h2><p><code>lograil</code> shares one immutable, frozen entry across all transports (zero-copy). Per-transport async writes each have their own queue, so a slow transport may lag behind a fast one — ordering is guaranteed <strong>per transport</strong>, not globally across transports. If you need strict global order, use a single transport or make all writes synchronous. Duplicate lines usually mean the same transport was added twice, or <code>redirectConsole()</code> is double-emitting — check <code>getTransports()</code>.</p><h2 id="_7-notes-when-passing-entries-across-processes-ipc" tabindex="-1">7. Notes when passing entries across processes (IPC) <a class="header-anchor" href="#_7-notes-when-passing-entries-across-processes-ipc" aria-label="Permalink to &quot;7. Notes when passing entries across processes (IPC)&quot;">​</a></h2><p>Entries are structured-cloned when sent over Electron IPC (the renderer transport ) After an entry crosses the boundary it is a <strong>new, independent object</strong> on the other side. Don&#39;t rely on identity; rely on the field values. See <a href="./immutability">Immutability</a>.</p>',30)])])}const g=o(n,[["render",a]]);export{p as __pageData,g as default};
